export {
  init,
  Message,
  Model,
  OutMessage,
  reflectChecked,
  setChecked,
  SetChecked,
  ToggledChecked,
  update,
  view,
} from "../switch";
export type {
  Commands,
  InitConfig,
  InitReturn,
  SwitchAttributes,
  Toggled,
  UpdateReturn,
  ViewInputs,
} from "../switch";

export {
  baseUiSwitchButtonClassName,
  baseUiSwitchDescriptionClassName,
  baseUiSwitchKnob,
  baseUiSwitchLabelClassName,
  baseUiSwitchRowClassName,
  baseUiSwitchTextClassName,
} from "./view";

export {
  switchButtonClassName as baseUiSwitchButtonClassName,
  switchDescriptionClassName as baseUiSwitchDescriptionClassName,
  switchKnob as baseUiSwitchKnob,
  switchLabelClassName as baseUiSwitchLabelClassName,
  switchRowClassName as baseUiSwitchRowClassName,
  switchTextClassName as baseUiSwitchTextClassName,
} from "../switch/view";

import { describe, expect, test } from "vitest";

import * as Switch from "./index";

describe("Base UI Switch registry view", () => {
  test("reuses the Foldkit Switch functional contract", () => {
    expect(Switch.init).toBeTypeOf("function");
    expect(Switch.update).toBeTypeOf("function");
    expect(Switch.view).toBeTypeOf("function");
    expect(Switch.baseUiSwitchKnob).toBeTypeOf("function");
  });
});
